import{_ as d,C as s,o as l,c as k,E as e,a4 as i,b as n,w as a,a as h,a5 as b}from"./chunks/framework.2-Vke5-n.js";const r="/arch-guidelines/assets/core_web_vitals.Dq1wi8Ex.png",A=JSON.parse('{"title":"Appendix","description":"","frontmatter":{"sidebarDepth":4,"title":"Appendix","author":"フューチャー株式会社","head":[["meta",{"name":"keywords","content":"性能テスト,Appendix"}]]},"headers":[],"relativePath":"documents/forPerformanceTest/appendix.md","filePath":"documents/forPerformanceTest/appendix.md"}'),x={name:"documents/forPerformanceTest/appendix.md"};function p(u,t,m,y,f,g){const c=s("page-title"),o=s("Mermaid");return l(),k("div",null,[e(c),t[1]||(t[1]=i('<p>本ページは、<a href="./performance_test.html">はじめての性能テスト</a>のAppendixである。</p><h2 id="画面の性能テスト" tabindex="-1">画面の性能テスト <a class="header-anchor" href="#画面の性能テスト" aria-label="Permalink to &quot;画面の性能テスト&quot;">​</a></h2><p>画面（UI）の性能テストを実施するかどうかは、システムの特性に応じて判断する。<br> 一般的にtoB向けの業務システムでは必須ではない。一方、toC向けのWebサービスなどユーザー体験がビジネスの価値に直結する場合は、画面性能指標の目標値を定めた上で性能テストを実施することが望ましい。</p><p>テストの分類や計画・準備などの本質的な進め方は、これまで説明してきた内容と変わらない。そのため、ここでは画面の性能テストならではのポイントをいくつか説明する。</p><h3 id="性能指標" tabindex="-1">性能指標 <a class="header-anchor" href="#性能指標" aria-label="Permalink to &quot;性能指標&quot;">​</a></h3><h4 id="web-vitals" tabindex="-1">Web Vitals <a class="header-anchor" href="#web-vitals" aria-label="Permalink to &quot;Web Vitals&quot;">​</a></h4><p>画面の性能指標として、処理時間項でも触れているweb.devが定義するWeb Vitalsを紹介する。</p><p>Web Vitalsとは、web.devが定義したWebページのユーザー体験を数値化する指標群である。「ページが速く表示されるか」「操作に素早く反応するか」「表示がガタつかないか」といった、ユーザーが体感する品質を客観的に測定できる。Web Vitalsが重要である理由は次の通りである。</p><ul><li><strong>ユーザー体験に直結する</strong>: 表示が遅い、操作しても反応がない、レイアウトがズレるといった問題は、離脱率や売上に直接影響する</li><li><strong>SEOに影響する</strong>: GoogleはCore Web Vitalsを検索ランキングのシグナルとして使用しており、スコアが悪いと検索順位が下がり得る</li></ul><h4 id="core-web-vitals" tabindex="-1">Core Web Vitals <a class="header-anchor" href="#core-web-vitals" aria-label="Permalink to &quot;Core Web Vitals&quot;">​</a></h4><p>Web Vitalsの中でも特に重要な3指標をCore Web Vitalsと呼ぶ。</p><p><img src="'+r+'" alt="Core Web Vitals"></p><p>各指標の意味と閾値は次の通りである。閾値は、優れたユーザー体験を提供するために満たす必要がある値として定義されている。</p><table tabindex="0"><thead><tr><th style="text-align:left;">指標</th><th style="text-align:left;">意味</th><th style="text-align:left;">閾値</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LCP（Largest Contentful Paint: 表示速度）</strong></td><td style="text-align:left;">ページ内で最も大きなコンテンツ（メイン画像、見出しテキストなど）が画面に描画されるまでの時間。ユーザーが「このページ、表示された」と感じるタイミングに相当する</td><td style="text-align:left;">ページの読み込み開始から2.5秒以内</td></tr><tr><td style="text-align:left;"><strong>INP（Interaction to Next Paint: 操作への応答性）</strong></td><td style="text-align:left;">ユーザーがクリック・タップ・キー入力などの操作をしてから、画面が次の描画を反映するまでの時間。ページ滞在中のすべての操作のうち、最も遅いものに近い値が報告される</td><td style="text-align:left;">200ms未満</td></tr><tr><td style="text-align:left;"><strong>CLS（Cumulative Layout Shift: 視覚的な安定性）</strong></td><td style="text-align:left;">ページの読み込み中や操作中に、要素が意図せず位置ズレを起こした量の累積値。例えば、記事を読んでいる最中に広告が挿入されてテキストが下にズレるような現象を数値化する</td><td style="text-align:left;">0.1未満に保つ</td></tr></tbody></table><p>多くのユーザーに良好な体験を提供できていると判断するには、モバイル・PCの各デバイスにおいて、ページ読み込みの75パーセンタイル値が上記の閾値を満たしていることが推奨される。</p><h4 id="推奨指標" tabindex="-1">推奨指標 <a class="header-anchor" href="#推奨指標" aria-label="Permalink to &quot;推奨指標&quot;">​</a></h4><p>性能テストの文脈では<strong>LCPとINPに対して目標値を設定する</strong>ことを推奨する。CLSはユーザー体験の文脈では重要であるが、性能指標とは異なるため対象外とする。</p><div class="tip custom-block"><p class="custom-block-title">Web Vitals以外の性能指標</p><p>Web Vitalsには他にも性能指標が存在するが、それぞれ次の理由で画面性能指標としては採用しない。</p><ul><li><strong>FCP（First Contentful Paint）</strong><br> ページ上で最初のコンテンツ（テキストや画像など）が描画されるまでの時間を表す。FCPはローディングスピナーや空のヘッダーでも発火してしまうため実ユーザーの体感とはズレがあり、LCPで代替可能なため対象外とする。</li><li><strong>TBT（Total Blocking Time）</strong><br> FCPの後にメインスレッドが入力の応答性を妨げるほど長くブロックされていた合計時間を表す。ラボ環境（ツールを使用し、一貫して制御された条件でページ読み込みをシミュレートできる環境）で計測する必要がある。有用な指標であるものの実ユーザー環境で測定できるINPで代替可能なため、対象外とする。</li><li><strong>TTFB（Time to First Byte）</strong><br> リソースのリクエストからレスポンスの最初のバイトが到着するまでの時間を表す。先述の通り、サーバーとネットワークの性能指標であるため、画面の性能指標としては対象外とする。</li></ul></div><h3 id="性能検証ツール" tabindex="-1">性能検証ツール <a class="header-anchor" href="#性能検証ツール" aria-label="Permalink to &quot;性能検証ツール&quot;">​</a></h3><p>画面の性能検証では、サーバーのレスポンスタイムだけでなく、ブラウザ上でのレンダリングやユーザー操作の体感速度を測定する必要がある。</p><p>画面性能指標として推奨しているLCPとINPを測定できるツールを選定する。</p>',21)),(l(),n(b,null,{default:a(()=>[e(o,{id:"mermaid-140",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20theme%3A%20neutral%0A%20%20layout%3A%20dagre%0A%20%20look%3A%20handDrawn%0A%20%20flowchart%3A%0A%20%20%20%20htmlLabels%3A%20true%0A%20%20%20%20nodeSpacing%3A%20100%0A%20%20%20%20rankSpacing%3A%20200%0A---%0Aflowchart%20LR%0A%20%20%20%20Q1%7B%22%E3%83%A9%E3%83%83%E3%82%B7%E3%83%A5%E3%83%86%E3%82%B9%E3%83%88%E3%81%AE%3Cbr%3E%E5%AE%9F%E6%96%BD%E3%81%8C%E5%BF%85%E8%A6%81%E3%81%8B%EF%BC%9F%22%7D%0A%20%20%20%20Q1%20--%20No%20--%3E%20Q2%7B%22Lighthouse%E3%81%A7%E8%A7%A3%E6%B6%88%E3%81%97%E3%81%AA%E3%81%84%3Cbr%3E%E3%82%A8%E3%83%83%E3%82%B8%E3%82%B1%E3%83%BC%E3%82%B9%E3%81%8C%3Cbr%3E%E5%AD%98%E5%9C%A8%E3%81%99%E3%82%8B%E3%81%8B%EF%BC%9F%22%7D%0A%20%20%20%20Q1%20--%20Yes%20--%3E%20Q3%7B%22Playwright%E3%81%AE%E8%B3%87%E7%94%A3%E3%82%92%3Cbr%3E%E6%B4%BB%E7%94%A8%E3%81%A7%E3%81%8D%E3%81%9D%E3%81%86%E3%81%8B%EF%BC%9F%22%7D%0A%20%20%20%20Q2%20--%20No%20--%3E%20Lighthouse%5B%22%3Cp%20style%3D'width%3A180px'%3ELighthouse%E3%82%92%E6%8E%A1%E7%94%A8%3C%2Fp%3E%22%5D%0A%20%20%20%20Q2%20--%20Yes%20--%3E%20WPT%5B%22%3Cp%20style%3D'width%3A180px'%3EWebPageTest%E3%82%92%E6%8E%A1%E7%94%A8%3C%2Fp%3E%22%5D%0A%20%20%20%20Q3%20--%20No%20--%3E%20K6%5B%22%3Cp%20style%3D'width%3A180px'%3Ek6-browser%E3%82%92%E6%8E%A1%E7%94%A8%3C%2Fp%3E%22%5D%0A%20%20%20%20Q3%20--%20Yes%20--%3E%20Artillery%5B%22%3Cp%20style%3D'width%3A180px'%3EArtillery%E3%82%92%E6%8E%A1%E7%94%A8%3C%2Fp%3E%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[h(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<p>決定木で分岐する各ツールについて、適用場面と選定理由は次の通りである。</p><ul><li><strong><a href="https://github.com/GoogleChrome/lighthouse" target="_blank" rel="noreferrer">Lighthouse</a></strong><br> ボリュームテストのみを実施する場合に使用し、単機能レベルでのLCP、INPのスコア化を推奨する。<a href="https://www.webpagetest.org/" target="_blank" rel="noreferrer">WebPageTest</a>や<a href="https://www.sitespeed.io/" target="_blank" rel="noreferrer">sitespeed.io</a>でも同様の計測はできる。ただし手軽さではLighthouseが一歩抜きん出ている。問題の切り分けや対策もLighthouse単体で十分実施できる。</li><li><strong>WebPageTest</strong><br> Lighthouse単体では解消しないエッジケースが存在する場合に、利用を検討する。</li><li><strong><a href="https://grafana.com/docs/k6/latest/using-k6-browser/" target="_blank" rel="noreferrer">k6-browser</a></strong><br> ボリュームテストに加えラッシュテストを実施しなければならない場合の第一候補とする。業界標準かつバックエンドテストとの統合が容易である。既にバックエンドの性能テストでk6を使用している場合は、導入コスト・維持コストの低減に繋げやすい。</li><li><strong>Artillery</strong><br> k6を使用しておらず、かつPlaywrightの資産・知見を活用できそうな場合に、使用を検討する。ただし、性能テスト用のケースと通常のテストケースが完全一致することは実際には多くない。</li></ul><p>各ツールの特徴を比較すると次の通りである。</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">Lighthouse</th><th style="text-align:left;">WebPageTest</th><th style="text-align:left;">sitespeed.io</th><th style="text-align:left;">k6-browser</th><th style="text-align:left;">Artillery</th></tr></thead><tbody><tr><td style="text-align:left;">提供元</td><td style="text-align:left;">Google</td><td style="text-align:left;">Catchpoint</td><td style="text-align:left;">OSSコミュニティ</td><td style="text-align:left;">Grafana Labs</td><td style="text-align:left;">Artillery Software</td></tr><tr><td style="text-align:left;">説明</td><td style="text-align:left;">Chromeで実行できる単体レベルの画面性能検証においてはデファクトスタンダードなツール</td><td style="text-align:left;">Webサービス経由で利用でき、実機と実回線でテストできる本格的な解析ツール</td><td style="text-align:left;">Dockerベースで動作し、継続的なパフォーマンスモニタリングと自動化に特化したツール</td><td style="text-align:left;">k6にChromium制御を組み込んだツール</td><td style="text-align:left;">Playwrightをスケール起動できるNode.js製のフルスタック負荷テストツール</td></tr><tr><td style="text-align:left;">ライセンス</td><td style="text-align:left;">Apache 2.0</td><td style="text-align:left;">Polyform Shield 1.0.0</td><td style="text-align:left;">MIT</td><td style="text-align:left;">AGPL-3.0</td><td style="text-align:left;">MPL-2.0</td></tr><tr><td style="text-align:left;">実行方法</td><td style="text-align:left;">Chrome DevTools / CLI / Node.js API</td><td style="text-align:left;">Webサービス / プライベートインスタンス / API</td><td style="text-align:left;">CLI / Docker</td><td style="text-align:left;">CLI / Docker / k6 Cloud / Kubernetes</td><td style="text-align:left;">CLI / Docker / Artillery Cloud / AWS Fargate</td></tr><tr><td style="text-align:left;">対応端末</td><td style="text-align:left;">⚠️ PC</td><td style="text-align:left;">✅️ PC・モバイル実機<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></td><td style="text-align:left;">⚠️ PC（エミュレート）</td><td style="text-align:left;">⚠️ PC（エミュレート）</td><td style="text-align:left;">⚠️ PC（エミュレート）</td></tr><tr><td style="text-align:left;">対応ブラウザ</td><td style="text-align:left;">⚠️ Chromeのみ</td><td style="text-align:left;">✅️ Chrome / Safari / Firefox / Edge</td><td style="text-align:left;">✅️ Chrome / Safari（macOSのみ） / Firefox / Edge</td><td style="text-align:left;">⚠️ Chromium（Chrome, Edge）系</td><td style="text-align:left;">✅️ Chrome / Safari / Firefox / Edge</td></tr><tr><td style="text-align:left;">LCP/INP計測</td><td style="text-align:left;">✅️ 可能</td><td style="text-align:left;">✅️ 可能</td><td style="text-align:left;">✅️ 可能</td><td style="text-align:left;">✅️ 可能</td><td style="text-align:left;">✅️ 可能</td></tr><tr><td style="text-align:left;">レポーティング</td><td style="text-align:left;">✅️ 100点満点のスコアと色分けで非エンジニアにも直感的</td><td style="text-align:left;">⚠️ 詳細なウォーターフォール図中心の専門家向けUI</td><td style="text-align:left;">✅️ Grafana連携により美しいレポート画面を生成可能</td><td style="text-align:left;">✅️ Grafana連携により美しいレポート画面を生成可能</td><td style="text-align:left;">⚠️ Cloud版または外部ツールでの整形が必要<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></td></tr><tr><td style="text-align:left;">性能対策立案</td><td style="text-align:left;">✅️ 具体的な改善策をTODO形式で提示</td><td style="text-align:left;">⚠️ 課題の発見・ボトルネックの特定まで</td><td style="text-align:left;">✅️ Lighthouseなどの評価エンジンを内包</td><td style="text-align:left;">❌️ 測定結果の提示まで</td><td style="text-align:left;">⚠️ 課題の発見・ボトルネックの特定まで</td></tr><tr><td style="text-align:left;">CIへの組み込み</td><td style="text-align:left;">✅️ 公式のLighthouse CI (LHCI)がある</td><td style="text-align:left;">⚠️ 可能だが大量実行は有料のAPIプランが必要</td><td style="text-align:left;">✅️ CI/CDパイプラインへの統合を前提に設計されており容易</td><td style="text-align:left;">✅️ GitHub Actionsなどの公式アクションが豊富であり容易</td><td style="text-align:left;">✅️ GitHub Actionsなどの公式アクションが豊富であり容易</td></tr><tr><td style="text-align:left;">ラッシュテスト対応</td><td style="text-align:left;">❌️ なし</td><td style="text-align:left;">❌️ なし</td><td style="text-align:left;">❌️ なし</td><td style="text-align:left;">✅️ 可能</td><td style="text-align:left;">✅️ 可能<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></td></tr><tr><td style="text-align:left;">導入コスト</td><td style="text-align:left;">✅️ Chromeがあれば即時利用可能</td><td style="text-align:left;">⚠️ Web上の公開テストは即時利用可能だがプライベート環境構築は手間</td><td style="text-align:left;">⚠️ Docker・Grafanaなどの知識が必要</td><td style="text-align:left;">⚠️ シナリオ作成と実行環境準備が必要</td><td style="text-align:left;">⚠️ シナリオ作成と実行環境準備が必要</td></tr><tr><td style="text-align:left;">価格</td><td style="text-align:left;">✅️ 無料</td><td style="text-align:left;">⚠️ APIの大量利用やプライベート環境構築などのPro機能は有料</td><td style="text-align:left;">✅️ 無料</td><td style="text-align:left;">✅️ ツール自体は無料、実行環境の費用は発生</td><td style="text-align:left;">⚠️ ツール自体は無料、実行環境やSaaS版の費用は発生</td></tr><tr><td style="text-align:left;">GitHubスター数</td><td style="text-align:left;">29.9k</td><td style="text-align:left;">3.2k</td><td style="text-align:left;">5.0k</td><td style="text-align:left;">29.4k<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></td><td style="text-align:left;">8.9k</td></tr><tr><td style="text-align:left;">ユースケース</td><td style="text-align:left;">コストを掛けずに画面性能検証を行いたい場合</td><td style="text-align:left;">Lighthouseでは解決しない性能問題の原因を分析したい場合 / 自社プロダクトと競合プロダクトの速度を比較したい場合 / 一連のユーザージャーニーでボトルネックを探りたい場合</td><td style="text-align:left;">CIで継続的に性能を確認したい場合</td><td style="text-align:left;">バックエンドの性能テストでk6を利用しており、高負荷を再現したい場合</td><td style="text-align:left;">Playwrightを利用しており、高負荷を再現したい場合</td></tr></tbody></table><h3 id="チューニング" tabindex="-1">チューニング <a class="header-anchor" href="#チューニング" aria-label="Permalink to &quot;チューニング&quot;">​</a></h3><p>画面の性能テストにおけるチューニングでは、ネットワーク転送量を削減し、キャッシュを活用する。<br> システム全体としては、アプリケーションロジックやデータベースレイヤーがボトルネックとなることが多い。そのため、それらの対応を検討した後、更なるチューニングの必要があれば実施する。</p><h4 id="データ転送量の削減" tabindex="-1">データ転送量の削減 <a class="header-anchor" href="#データ転送量の削減" aria-label="Permalink to &quot;データ転送量の削減&quot;">​</a></h4><h5 id="コンテンツ圧縮" tabindex="-1">コンテンツ圧縮 <a class="header-anchor" href="#コンテンツ圧縮" aria-label="Permalink to &quot;コンテンツ圧縮&quot;">​</a></h5><p>HTML/CSS/JavaScript/画像などの静的リソースを圧縮して送信する。<br> 2026年4月時点ではgzipよりも圧縮率の高いBrotliに対応しているブラウザも多く、導入が推奨される。</p><div class="tip custom-block"><p class="custom-block-title">Brotli</p><p>Brotliは2015年にGoogleがWeb向けに公開した圧縮アルゴリズムである。圧縮率はトップクラスであり、圧縮レベル次第ではgzipよりも高い圧縮効果を発揮する（テキスト系ファイルでは15％〜25％程度軽量化できる）。</p><p>主要なブラウザでもBrotliエンコーディングに対応しており、多くのCDN（Amazon CloudFront、Google Cloud CDN、Azure CDN）でも圧縮形式としてサポートしている。</p></div><h5 id="画像の最適化" tabindex="-1">画像の最適化 <a class="header-anchor" href="#画像の最適化" aria-label="Permalink to &quot;画像の最適化&quot;">​</a></h5><p>JPEGやPNGの代わりに、より圧縮率の高いWebPやAVIFを使用する。<br> また、デバイス（スマホ・PC）に合わせて適切なサイズの画像を出し分ける（<code>&lt;picture&gt;</code> タグや <code>srcset</code> 属性の活用）。</p><p>詳細は「<a href="https://future-architect.github.io/arch-guidelines/documents/forWebFrontend/web_frontend_guidelines.html#%E7%94%BB%E5%83%8F" target="_blank" rel="noreferrer">Webフロントエンド設計ガイドライン - 画像</a>」を参照されたい。</p><h5 id="コードのminify" tabindex="-1">コードのMinify <a class="header-anchor" href="#コードのminify" aria-label="Permalink to &quot;コードのMinify&quot;">​</a></h5><p>Minifyによりファイルサイズを縮小する。Minifyでは、CSSやJavaScriptから不要な改行、スペース、コメントを削除し、変数名や関数名を短く置き換える。</p><p>詳細は「<a href="https://future-architect.github.io/arch-guidelines/documents/forWebFrontend/web_frontend_guidelines.html#minify" target="_blank" rel="noreferrer">Webフロントエンド設計ガイドライン - Minify</a>」を参照されたい。</p><h4 id="キャッシュの活用" tabindex="-1">キャッシュの活用 <a class="header-anchor" href="#キャッシュの活用" aria-label="Permalink to &quot;キャッシュの活用&quot;">​</a></h4><h5 id="cdnの活用" tabindex="-1">CDNの活用 <a class="header-anchor" href="#cdnの活用" aria-label="Permalink to &quot;CDNの活用&quot;">​</a></h5><p>HTML/CSS/JavaScript/画像などの静的リソースをエッジサーバーにキャッシュし、物理的に最も近いサーバーから応答を返却させる。</p><h5 id="ブラウザキャッシュの制御" tabindex="-1">ブラウザキャッシュの制御 <a class="header-anchor" href="#ブラウザキャッシュの制御" aria-label="Permalink to &quot;ブラウザキャッシュの制御&quot;">​</a></h5><p>HTTPヘッダーの <code>Cache-Control</code> を適切に設定し、静的ファイルはブラウザに長期間キャッシュ（有効期限を長く設定）させる。</p><p><code>ETag</code> や <code>Last-Modified</code> を用いて、ファイルに変更がない場合は「304 Not Modified」を返し、ダウンロードをスキップさせる。</p><p>詳細は「<a href="https://future-architect.github.io/arch-guidelines/documents/forWebFrontend/web_frontend_guidelines.html#%E3%82%AD%E3%83%A3%E3%83%83%E3%82%B7%E3%83%A5" target="_blank" rel="noreferrer">Webフロントエンド設計ガイドライン - キャッシュ</a>」を参照されたい。</p><h4 id="ネットワーク通信の最適化" tabindex="-1">ネットワーク通信の最適化 <a class="header-anchor" href="#ネットワーク通信の最適化" aria-label="Permalink to &quot;ネットワーク通信の最適化&quot;">​</a></h4><h5 id="画像の遅延読み込み-lazy-load" tabindex="-1">画像の遅延読み込み（Lazy Load） <a class="header-anchor" href="#画像の遅延読み込み-lazy-load" aria-label="Permalink to &quot;画像の遅延読み込み（Lazy Load）&quot;">​</a></h5><p>画面のファーストビュー（スクロールせずに見える範囲）に入っていない画像は、スクロールして近づくまで読み込みを遅延させる（<code>&lt;img loading=&quot;lazy&quot;&gt;</code> の活用）。</p><h5 id="http-2またはhttp-3の導入" tabindex="-1">HTTP/2またはHTTP/3の導入 <a class="header-anchor" href="#http-2またはhttp-3の導入" aria-label="Permalink to &quot;HTTP/2またはHTTP/3の導入&quot;">​</a></h5><p>HTTP/2・HTTP/3では、1つのコネクションで複数のリソースを並列して送受信（多重化）できるため、通信のオーバーヘッドを大幅に削減できる。</p><p>Amazon CloudFrontなど主要なCDNを用いている場合は設定変更のみでHTTP/2・HTTP/3化でき、導入自体は簡易である。実施の際は、次の理由からHTTP/2とHTTP/3双方の有効化を推奨する。</p><ul><li><strong>HTTP/2の弱点</strong>: 通信環境が極端に悪い場合、一部のパケットのロスが発生すると、そのパケットが再送されるまで同一コネクション内の全てのデータ通信が一時的に停止してしまう</li><li><strong>HTTP/3による解消</strong>: HTTP/3ではこの問題が解消されており、双方を有効化することでHTTP/2のデメリットを補える</li></ul><p>あわせて、並列リクエストによるメリットを活かすため、配信するファイルの粒度も次の通り調整する。</p><ul><li>CSSやJavaScriptを巨大な単一ファイルとしてビルド・配信するのではなく、分割して配信することを推奨する</li><li>ただし、むやみに数百個まで分割すると先述のgzipやBrotliの圧縮効率が下がるため、過度な分割は避ける</li></ul><h2 id="チェックリスト" tabindex="-1">チェックリスト <a class="header-anchor" href="#チェックリスト" aria-label="Permalink to &quot;チェックリスト&quot;">​</a></h2><h3 id="a-計画時チェックリスト" tabindex="-1">A. 計画時チェックリスト <a class="header-anchor" href="#a-計画時チェックリスト" aria-label="Permalink to &quot;A. 計画時チェックリスト&quot;">​</a></h3><p>テスト計画から準備完了までに確認すべき項目をまとめている。<br> 各項目は「決まっているか」「ステークホルダー間で合意できているか」の両面で確認することが望ましい。</p><h4 id="a-1-目的とスコープ" tabindex="-1">A-1. 目的とスコープ <a class="header-anchor" href="#a-1-目的とスコープ" aria-label="Permalink to &quot;A-1. 目的とスコープ&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 性能テストの主目的が明確になっている（複数選択可） <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 性能指標値の評価</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 安定性・信頼性の評価</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スケーラビリティの評価</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 最適なキャパシティプランニング</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> その他</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 主目的に重みづけがされており、優先順位が明確である</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> テスト対象システムの範囲が明確である <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 外部システム / 共通基盤との連携の扱いが決まっている（含める / 含めない / スタブで代替）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> フロントエンドの扱いが決まっている（含める / 含めない）</li></ul></li></ul><h4 id="a-2-システム諸元" tabindex="-1">A-2. システム諸元 <a class="header-anchor" href="#a-2-システム諸元" aria-label="Permalink to &quot;A-2. システム諸元&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> データ諸元が定義されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DBの全テーブルについてレコード件数の見積もりがある</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 取り扱うファイルの最大 / 平均サイズが定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 何年後の状態（例. 3年後、5年後）を基準とするかが決まっている</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 負荷諸元が定義されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 通常時 / ピーク時 / スパイク時など状態別に値が定義されている</li></ul></li></ul><h4 id="a-3-目標値" tabindex="-1">A-3. 目標値 <a class="header-anchor" href="#a-3-目標値" aria-label="Permalink to &quot;A-3. 目標値&quot;">​</a></h4><h5 id="スループット" tabindex="-1">スループット <a class="header-anchor" href="#スループット" aria-label="Permalink to &quot;スループット&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 算出根拠が明確である（既存システムのアクセスログ / 想定ユースケースなど）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 安全係数（例. 2倍、3倍）が考慮されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 負荷状態（通常時 / ピーク時など）ごとに値が定義されている</li></ul><h5 id="処理時間-オンライン処理" tabindex="-1">処理時間（オンライン処理） <a class="header-anchor" href="#処理時間-オンライン処理" aria-label="Permalink to &quot;処理時間（オンライン処理）&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 業界標準の指標値（例. TTFB 800ms）やベースラインシステムを参照して妥当な値が定められている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 機能特性ごとに目標値が細分化されている（コア系 / 標準系 / 管理系、参照 / 更新など）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> パーセンタイル値（例. p90、p95）で順守率が定められている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 負荷状態（通常時 / ピーク時 / 縮退時）ごとに順守率が調整されている</li></ul><h5 id="処理時間-バッチ処理" tabindex="-1">処理時間（バッチ処理） <a class="header-anchor" href="#処理時間-バッチ処理" aria-label="Permalink to &quot;処理時間（バッチ処理）&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> バッチウィンドウを基準に上限が決まっている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 順守率は「再実行の余裕があるか」など運用面を含めた基準になっている</li></ul><h5 id="リソース使用率" tabindex="-1">リソース使用率 <a class="header-anchor" href="#リソース使用率" aria-label="Permalink to &quot;リソース使用率&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 対象コンポーネント（APサーバー、DBサーバー、キャッシュサーバーなど）ごとに定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> CPU使用率、メモリ使用率は最低限定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 上限値（例. 通常時50-60％、ピーク時80％以下）が定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 下限値（過剰スペックを避けるため、例. ピーク時30-40％以上）が定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> オートスケールのトリガー閾値と整合が取れている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ワンショットのバッチサーバーについては「使い切る」前提の目標が別途定められている</li></ul><h4 id="a-4-テストの段取りと完了基準" tabindex="-1">A-4. テストの段取りと完了基準 <a class="header-anchor" href="#a-4-テストの段取りと完了基準" aria-label="Permalink to &quot;A-4. テストの段取りと完了基準&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 実施するテスト種別と順序が決まっている（推奨: ボリューム → ラッシュ → ロングラン → ストレス）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スパイク性のあるシステムの場合、スパイクテストの実施が計画されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 各テストの完了基準（合格基準）が定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 各テストの対象機能 / シナリオが選定されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ボリュームテストの対象機能が選定されている（原則全機能、優先度付け基準も明確）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ラッシュ / ロングラン / ストレスの対象シナリオが選定されている（スループット算出時の根拠と整合）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> バッチ処理を含む時間帯のシナリオが組み込まれている</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 各機能 / シナリオの試行回数の方針がある（オンライン100回以上が目安）</li></ul><h4 id="a-5-ツール選定" tabindex="-1">A-5. ツール選定 <a class="header-anchor" href="#a-5-ツール選定" aria-label="Permalink to &quot;A-5. ツール選定&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 負荷ツールが選定されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> CI/CD組み込みやコード管理のしやすさが考慮されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 想定する最大負荷を生成できる</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> モニタリングツールが選定されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> APMの要否、外部監視サービスの可否を踏まえた判断になっている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 本番運用で利用するツールと揃えられている</li></ul></li></ul><h4 id="a-6-メトリクス" tabindex="-1">A-6. メトリクス <a class="header-anchor" href="#a-6-メトリクス" aria-label="Permalink to &quot;A-6. メトリクス&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> インフラメトリクス（CPU、メモリ、ネットワークI/O、ディスクI/Oなど）が定義されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 利用するクラウドマネージドサービス固有のメトリクスが定められている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DBメトリクスが定義されている（スロークエリ、待機イベント、コネクション状況など）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ランタイムメトリクスが定義されている（ヒープ、GC、スレッド数など）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> サービス / アプリケーションメトリクス（Rate / Errors / Duration）が定義されている</li></ul><h4 id="a-7-テスト環境" tabindex="-1">A-7. テスト環境 <a class="header-anchor" href="#a-7-テスト環境" aria-label="Permalink to &quot;A-7. テスト環境&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 本番環境または同等構成の環境が確保されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 環境を占有して利用できる</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 本番同等のスペック・台数で構成されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 必要に応じて並行作業用に複数環境が確保されている</li></ul><h4 id="a-8-スケジュール" tabindex="-1">A-8. スケジュール <a class="header-anchor" href="#a-8-スケジュール" aria-label="Permalink to &quot;A-8. スケジュール&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 計画 / 準備工数が、実行 / チューニング工数と同等以上に確保されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 長時間実行ケース（ロングランなど）の再実行リスクを織り込んだバッファがある</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 不確実性の高い特性（新規システム、複数処理方式の混在、マルチテナント、外部連携多数など）を踏まえたバッファがある</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> テスト同士で相互影響するもの（例. ストレステストとロングランテスト）の並行実施を避けた計画になっている</li></ul><h4 id="a-9-環境構築・設定" tabindex="-1">A-9. 環境構築・設定 <a class="header-anchor" href="#a-9-環境構築・設定" aria-label="Permalink to &quot;A-9. 環境構築・設定&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 負荷ツールを動かすコンピューティングリソースが構築されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 負荷ツールから各種リソース（DB、S3、SQSなど）へのリーチャビリティが確保されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ログレベルが本番相当（INFO以上が一般的）に設定されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> キャッシュの有効化 / 無効化方針がテスト種別ごとに定められている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> HTTPキャッシュの方針が定められている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> アプリケーションキャッシュの方針が定められている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DBキャッシュの方針が定められている</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> オートスケールの有効化 / 無効化方針がテスト種別ごとに定められている</li></ul><h4 id="a-10-データ準備" tabindex="-1">A-10. データ準備 <a class="header-anchor" href="#a-10-データ準備" aria-label="Permalink to &quot;A-10. データ準備&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> データ作成方法が決定されている（本番エクスポート / ファイルインポート / 手続き型SQL / INSERT / 実機能利用）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 大量データ作成時の事前準備が検討されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> インデックス / 外部キー制約の一時削除が検討されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DBスペックの一時増強が検討されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> autovacuumの停止と完了後のANALYZE/VACUUMが検討されている</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> データパターンが現実的である <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> カーディナリティ（取りうる値のバリエーション）が適切である</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スキュー（特定キーへの偏り）が現実に即している</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 関連テーブルの件数比率が実態に近い</li></ul></li></ul><h4 id="a-11-テストスクリプト" tabindex="-1">A-11. テストスクリプト <a class="header-anchor" href="#a-11-テストスクリプト" aria-label="Permalink to &quot;A-11. テストスクリプト&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 事前処理 / テスト本体 / 事後処理が分離されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 計測対象に事前 / 事後処理の時間が混入しないようになっている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 繰り返し実行可能（冪等）になっている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 一意制約のあるカラムに動的な値が生成されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 事後処理またはリストアでクリーンアップ可能になっている</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 現実的な負荷パターンが再現されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 思考時間が挟まれている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> リクエストパラメータが分散されている（キャッシュヒット率の過大評価を防ぐ）</li></ul></li></ul><h4 id="a-12-その他の準備" tabindex="-1">A-12. その他の準備 <a class="header-anchor" href="#a-12-その他の準備" aria-label="Permalink to &quot;A-12. その他の準備&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スタブが用意・有効化されている（外部依存がある場合） <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 独立プロセス / サーバーとして稼働させる構成が原則となっている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 一定の遅延を含む応答を十分なスループットで返せる</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> メトリクスダッシュボードが用意されている <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 詳細モニタリング（例. CloudWatch Container Insights、RDS Database Insights）が有効化されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DBの拡張機能（例. pg_stat_statements、auto_explain）が有効化されている</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 素振り（負荷ツールでのウォームアップ実行）が完了している <ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 目標RPSの数倍まで安定して負荷生成できる</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> VUに余裕がある / ファイル記述子やマシンリソースに余裕がある</li></ul></li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> クラウドのクォータ緩和申請が必要に応じて完了している（実施1〜2週間前）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DDoS的な負荷テストの場合はクラウド事業者への申請が完了している</li></ul><h3 id="b-実施後チェックリスト" tabindex="-1">B. 実施後チェックリスト <a class="header-anchor" href="#b-実施後チェックリスト" aria-label="Permalink to &quot;B. 実施後チェックリスト&quot;">​</a></h3><p>各テスト実施後とレポーティング段階で確認すべき項目をまとめている。</p><p>「結果が完了基準を満たしているか」と「結果を正しく評価できるだけの情報が揃っているか」の両面で確認する。</p><h4 id="b-1-ボリュームテスト" tabindex="-1">B-1. ボリュームテスト <a class="header-anchor" href="#b-1-ボリュームテスト" aria-label="Permalink to &quot;B-1. ボリュームテスト&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 対象機能の処理時間が目標値をクリアしている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> バッチ処理についてはスループット（必要な場合）も目標値をクリアしている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 機能単位の処理時間内訳が把握できている（ネットワーク / アプリ / DB / 外部呼び出し）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 問題箇所・改善余地のある箇所に対し分析・チューニングが行われている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> SQLの実行計画が確認され、インデックスや作業メモリの最適化が行われている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 試行回数が十分（オンラインは100回以上を目安）に確保されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 最終確定したインフラ構成で再計測が行われている（構成が途中で変わった場合）</li></ul><h4 id="b-2-ラッシュテスト" tabindex="-1">B-2. ラッシュテスト <a class="header-anchor" href="#b-2-ラッシュテスト" aria-label="Permalink to &quot;B-2. ラッシュテスト&quot;">​</a></h4><h5 id="性能指標値" tabindex="-1">性能指標値 <a class="header-anchor" href="#性能指標値" aria-label="Permalink to &quot;性能指標値&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 全負荷パターン（通常時 / ピーク時 / 縮退時）で処理時間とスループットが目標値をクリアしている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 機能単位で見ても、ボリュームテスト時からの劣化が許容範囲内である</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 同時アクセスに伴う性能劣化部分について分析・対応が行われている</li></ul><h5 id="リソース・エラー" tabindex="-1">リソース・エラー <a class="header-anchor" href="#リソース・エラー" aria-label="Permalink to &quot;リソース・エラー&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> リソース使用率が目標値の範囲内に収まっている（上限・下限の両面）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 同時アクセスに伴う意図しないエラーが発生していない</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> エラー内訳が分析され、設計上許容されるものか異常かの切り分けができている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> メッセージキューを介した非同期処理がある場合、メッセージが滞留せず捌けている</li></ul><h5 id="キャパシティプランニング" tabindex="-1">キャパシティプランニング <a class="header-anchor" href="#キャパシティプランニング" aria-label="Permalink to &quot;キャパシティプランニング&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 性能要件を達成できる最小限の構成が比較検証されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> APサーバーとDBサーバーなど、変数を1つずつ動かして比較検証されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スケールアップとスケールアウトの比較がされている（水平スケール優先が原則）</li></ul><h4 id="b-3-ロングランテスト" tabindex="-1">B-3. ロングランテスト <a class="header-anchor" href="#b-3-ロングランテスト" aria-label="Permalink to &quot;B-3. ロングランテスト&quot;">​</a></h4><h5 id="性能指標値-1" tabindex="-1">性能指標値 <a class="header-anchor" href="#性能指標値-1" aria-label="Permalink to &quot;性能指標値&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 全期間にわたって処理時間・スループットが目標値をクリアしている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 開始区間と終了区間の比較で劣化していない</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> エラー率が時間とともに悪化していない</li></ul><h5 id="安定性・信頼性" tabindex="-1">安定性・信頼性 <a class="header-anchor" href="#安定性・信頼性" aria-label="Permalink to &quot;安定性・信頼性&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> メモリ使用率に右肩上がりの推移がない</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> アプリケーションランタイムメモリ（ヒープなど）の時系列推移を確認し、リーク兆候がない</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> DBコネクション、アプリケーションスレッドが枯渇せず、適切に解放されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> GC（特にFull GC）の頻度・実行時間が極端に上がっていない</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 期間中に動くべき定期バッチが想定通り動作している</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> テスト実行時間が、システムの連続稼働サイクル（または定期リフレッシュ間隔）を網羅している</li></ul><h4 id="b-4-ストレステスト" tabindex="-1">B-4. ストレステスト <a class="header-anchor" href="#b-4-ストレステスト" aria-label="Permalink to &quot;B-4. ストレステスト&quot;">​</a></h4><h5 id="スケーラビリティ" tabindex="-1">スケーラビリティ <a class="header-anchor" href="#スケーラビリティ" aria-label="Permalink to &quot;スケーラビリティ&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 現行構成における限界性能（限界RPSなど）が特定できている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 限界到達時のボトルネックコンポーネントが特定できている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ボトルネックを増強することで性能が実際に向上することが検証できている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 限界性能を超えた場合の増強ステップ（順序・対象）が整理されている</li></ul><h5 id="オートスケール" tabindex="-1">オートスケール <a class="header-anchor" href="#オートスケール" aria-label="Permalink to &quot;オートスケール&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スケールアウト・スケールインのトリガー閾値が期待通り発動している</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 閾値・継続期間・クールダウンの設定が、負荷変動スピードに対して適切である</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 新規ノードの立ち上がり時間が負荷増加スピードに追従できている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スケールイン時のグレースフルシャットダウンが正しく動作している</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> スケール上限・下限の設定値が妥当である</li></ul><h4 id="b-5-レポーティング" tabindex="-1">B-5. レポーティング <a class="header-anchor" href="#b-5-レポーティング" aria-label="Permalink to &quot;B-5. レポーティング&quot;">​</a></h4><h5 id="全体構成" tabindex="-1">全体構成 <a class="header-anchor" href="#全体構成" aria-label="Permalink to &quot;全体構成&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> テスト概要が記載されている（目的、スコープ、カテゴリ、要件・目標値）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 各テスト（ボリューム / ラッシュ / ロングラン / ストレス）の結果がそれぞれ整理されている</li></ul><h5 id="各結果の品質" tabindex="-1">各結果の品質 <a class="header-anchor" href="#各結果の品質" aria-label="Permalink to &quot;各結果の品質&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 統計値（min/avg/p50/p80/p90/p95/max）が目標値とともに表形式で整理されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 時系列推移が必要な箇所はグラフキャプチャが添付されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> グラフ上の異常箇所・気になる箇所には注釈・考察が補記されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 機能単位 / シナリオ単位の粒度で分析されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> エラーが発生している場合、内訳と原因・対応方針が整理されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> リソース使用状況がコンポーネント別に整理されている</li></ul><h5 id="ロングラン特有" tabindex="-1">ロングラン特有 <a class="header-anchor" href="#ロングラン特有" aria-label="Permalink to &quot;ロングラン特有&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> ランプアップ / ランプダウンを避けた区間で開始 / 終了の比較が行われている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> アプリケーションランタイムメモリの時系列グラフが添付されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> GCの頻度・実行時間の推移が記載されている</li></ul><h5 id="キャパシティプランニング-1" tabindex="-1">キャパシティプランニング <a class="header-anchor" href="#キャパシティプランニング-1" aria-label="Permalink to &quot;キャパシティプランニング&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 各構成パターンの比較検証結果が表形式で整理されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 採用構成の選定根拠（性能要件達成・コスト効率）が明確である</li></ul><h5 id="残存リスクと将来の見通し" tabindex="-1">残存リスクと将来の見通し <a class="header-anchor" href="#残存リスクと将来の見通し" aria-label="Permalink to &quot;残存リスクと将来の見通し&quot;">​</a></h5><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 限界性能と、将来的な負荷増加に対する増強ステップが明記されている</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 残存するリスク（未解消のチューニング項目、想定外の挙動など）が明文化されている</li></ul><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>US/EU/Asiaなどの粒度で実行ロケーションを選択できる他、5G/3Gなど回線を選ぶこともできる <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>v2.0.22からCLIのHTML出力機能が削除されており、視覚化にはArtillery Cloudへ生データの送信またはGrafanaなど外部ツール連携が必要 <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p>k6がネイティブで動くのに対し、ArtilleryはNode.jsで稼働する分負荷を掛ける側のリソース効率は劣る <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p>2026.3時点ではk6本体に統合されており、k6のスター数を記載 <a href="#fnref4" class="footnote-backref">↩︎</a></p></li></ol></section>',101))])}const q=d(x,[["render",p]]);export{A as __pageData,q as default};
